    } else if (TILING_KEY_IS(1020)) {
        GENERAL_OP_IMPL(KernelRmsNormWholeReduceSum, float, false);
    } else if (TILING_KEY_IS(1030)) {
        GENERAL_OP_IMPL(KernelRmsNormWholeReduceSum, bfloat16_t, false);
