#define INIT_AND_PROCESS_310P                       \
    do {                                            \
        op.Init(x, y, scale, nullptr, &tilingData); \
        op.Process();                               \
    } while (0)
#else
#define INIT_AND_PROCESS                                                      \
    do {                                                                      \
        op.Init(x, smooth_scales, y, scale, nullptr, workSpace, &tilingData); \
        op.Process();                                                         \
    } while (0)

#define INIT_AND_PROCESS_MOE                                                               \
    do {                                                                                   \
