    WaitFlag<HardEvent::V_S>(eventID);
}

__aicore__ inline uint64_t ComputeViewedRowOffset(uint64_t linearIndex, uint64_t firstDimStrideRows,
                                                  uint64_t varStride0Elements, uint64_t scatterLength)
{
    if (firstDimStrideRows == 0) {
        return linearIndex * scatterLength;
    }
    uint64_t i0 = linearIndex / firstDimStrideRows;
    uint64_t rest = linearIndex - i0 * firstDimStrideRows;
    return i0 * varStride0Elements + rest * scatterLength;
}

// 统一处理 view-stride0 与连续两条路径的输出偏移计算。
template <bool isViewStride0>
__aicore__ inline uint64_t ResolveOutOffset(uint64_t linearIndex, uint64_t scatterLength, uint64_t firstDimStrideRows,
                                            uint64_t varStride0Elements, uint64_t tileOffsetElements)
{
    if constexpr (isViewStride0) {
        return ComputeViewedRowOffset(linearIndex, firstDimStrideRows, varStride0Elements, scatterLength) +
               tileOffsetElements;
    } else {
        return linearIndex * scatterLength + tileOffsetElements;
    }
}

// 计算 block 分布参数
__aicore__ inline void CalcBlockDistribution(uint64_t blockIdx, uint64_t frontNum, uint64_t frontRow, uint64_t tailRow,
                                             uint64_t& computeRow, uint64_t& start)
{
    if (blockIdx >= frontNum) {
        computeRow = tailRow;
        start = frontNum * frontRow + (blockIdx - frontNum) * computeRow;
    } else {
        computeRow = frontRow;
        start = blockIdx * computeRow;
    }
}

__aicore__ inline void ComputeLinearIndexFromIndices(LocalTensor<int>& indicesLocal,
                                                     LocalTensor<int>& indicesOriginLocal,
                                                     LocalTensor<int>& addTmpLocal, LocalTensor<int>& rangeLocal,
                                                     const uint64_t* indicesMask, uint64_t indexDim, uint64_t rows)
{
    int32_t mulValue = static_cast<int32_t>(indexDim * sizeof(int));
    Duplicate<int>(indicesLocal, 0, rows);
    CreateVecIndex(rangeLocal, (int)0, rows);
    PipeBarrier<PIPE_V>();
    Muls(rangeLocal, rangeLocal, mulValue, rows);
    PipeBarrier<PIPE_V>();
    for (uint64_t i = 0; i < indexDim; ++i) {
        if (i != 0) {
            Adds(rangeLocal, rangeLocal, (int)(sizeof(int)), rows);
            PipeBarrier<PIPE_V>();
        }
        LocalTensor<uint32_t> rangeCasted = rangeLocal.ReinterpretCast<uint32_t>();
        Gather(addTmpLocal, indicesOriginLocal, rangeCasted, (uint32_t)0, (uint32_t)rows);
        PipeBarrier<PIPE_V>();
        Muls(addTmpLocal, addTmpLocal, (int)indicesMask[i], rows);
        PipeBarrier<PIPE_V>();
        Add(indicesLocal, indicesLocal, addTmpLocal, rows);
        PipeBarrier<PIPE_V>();
    }
}

template <typename T, bool isViewStride0>
__aicore__ inline void DoScatterCopy(LocalTensor<T>& updateLocal, GlobalTensor<T>& updatesGm, GlobalTensor<T>& outputGm,
                                     uint64_t gmOffset, uint64_t tileLength, int64_t linearIndex, uint64_t tileIdx,
                                     uint64_t scatterTileLength, uint64_t firstDimStrideRows,
                                     uint64_t varStride0Elements, uint64_t scatterLength)
{
    DataCopyExtParams updateCopyParams{1, static_cast<uint32_t>(tileLength * sizeof(T)), 0, 0, 0};
    DataCopyPadExtParams<T> padParams{true, 0, 0, 0};
    DataCopyPad(updateLocal, updatesGm[gmOffset], updateCopyParams, padParams);
    PipeMte2ToS();

    uint64_t outOffset = ResolveOutOffset<isViewStride0>(static_cast<uint64_t>(linearIndex), scatterLength,
                                                         firstDimStrideRows, varStride0Elements,
                                                         tileIdx * scatterTileLength);
    DataCopyExtParams outParams{1, static_cast<uint32_t>(tileLength * sizeof(T)), 0, 0, 0};
    DataCopyPad(outputGm[outOffset], updateLocal, outParams);
    PipeMte3ToS();
}

template <typename T, bool isViewStride0 = false>
class LargeIndexKernel {
public:
    __aicore__ inline LargeIndexKernel() = delete;
    __aicore__ inline LargeIndexKernel(GM_ADDR indices, GM_ADDR updates, GM_ADDR output,
                                       const ScatterNdUpdateSkArch22TilingData& tiling, TPipe& pipe)
    {
        InitParams(tiling);
        InitBuffers(pipe);
        SetGmAddr(indices, updates, output, tiling);
    }

    __aicore__ inline void InitParams(const ScatterNdUpdateSkArch22TilingData& tiling)
    {
        blockIdx_ = GetBlockIdx();

        CalcBlockDistribution(blockIdx_, tiling.scatterTiling.frontNum, tiling.scatterTiling.frontRow,
                              tiling.scatterTiling.tailRow, computeRow_, start_);
        end_ = start_ + computeRow_;

        startInt64_ = static_cast<int64_t>(start_);
        endInt64_ = static_cast<int64_t>(end_);

        indexDim_ = tiling.linearIndexTiling.indexDim;
        blockLength_ = tiling.linearIndexTiling.blockLength;
        blockNum_ = tiling.linearIndexTiling.blockNum;
        blockRemainLength_ = tiling.linearIndexTiling.blockRemainLength;

        scatterLength_ = tiling.scatterTiling.scatterLength;
        ubLengthForUpdates_ = tiling.scatterTiling.ubLengthForUpdates;
        scatterTileNum_ = tiling.scatterTiling.scatterTileNum;
        scatterTileLength_ = tiling.scatterTiling.scatterTileLength;
        scatterTileTail_ = tiling.scatterTiling.scatterTileTail;

        for (uint64_t i = 0; i < indexDim_; ++i) {
            indicesMask_[i] = tiling.linearIndexTiling.indicesMask[i];
        }

        varStride0Elements_ = tiling.viewTiling.varStride0Elements;
        firstDimStrideRows_ = tiling.viewTiling.firstDimStrideRows;
    }

    __aicore__ inline void InitBuffers(TPipe& pipe)
    {
        uint64_t indicesInt64Size = ((blockLength_ * indexDim_ * 2) + ALIGN_NUM - 1) & ~(ALIGN_NUM - 1);
        uint64_t updateBufBytes = (ubLengthForUpdates_ * sizeof(T) + 31) & ~31ULL;

        pipe.InitBuffer(indicesBuf, indicesInt64Size * sizeof(int));
        pipe.InitBuffer(updateBuf, updateBufBytes);

        indicesInt64Local = indicesBuf.Get<int>().ReinterpretCast<int64_t>();
        updateLocal = updateBuf.Get<T>();
    }

    __aicore__ inline void SetGmAddr(GM_ADDR indices, GM_ADDR updates, GM_ADDR output,
                                     const ScatterNdUpdateSkArch22TilingData& tiling)
    {
        indicesGmInt64_.SetGlobalBuffer((__gm__ int64_t*)indices);
        updatesGm_.SetGlobalBuffer((__gm__ T*)updates);
        outputGm_.SetGlobalBuffer((__gm__ T*)output);
    }

    __aicore__ inline void Process()
    {
        for (uint64_t blockIdx = 0; blockIdx < blockNum_; ++blockIdx) {
            ProcessOneBlock(blockIdx, false);
        }
        if (blockRemainLength_ != 0) {
            ProcessOneBlock(blockNum_, true);
        }
    }

    __aicore__ inline void ProcessOneBlock(uint64_t blockIdx, bool isTail)
    {
        uint64_t copyRow = isTail ? blockRemainLength_ : blockLength_;
        CopyInInt64(blockIdx, isTail);

        for (uint64_t i = 0; i < copyRow; ++i) {
            int64_t linearIndex = ComputeLinearIndex(i);
            if (linearIndex >= startInt64_ && linearIndex < endInt64_) {
                ScatterUpdate(i, linearIndex);
            }
        }
    }

    __aicore__ inline void CopyInInt64(uint64_t blockIdx, bool isTail)
    {
        uint64_t indicesOffset = blockIdx * blockLength_ * indexDim_;
        uint64_t copyRow = isTail ? blockRemainLength_ : blockLength_;

        DataCopyExtParams copyParams{1, static_cast<uint32_t>(copyRow * indexDim_ * sizeof(int64_t)), 0, 0, 0};
        DataCopyPadExtParams<int64_t> padParams{true, 0, 0, 0};
        DataCopyPad(indicesInt64Local, indicesGmInt64_[indicesOffset], copyParams, padParams);
        PipeMte2ToS();
    }

    __aicore__ inline int64_t ComputeLinearIndex(uint64_t rowIdx)
    {
        int64_t linearIndex = 0;
        for (uint64_t dim = 0; dim < indexDim_; ++dim) {
            int64_t idxValue = indicesInt64Local.GetValue(rowIdx * indexDim_ + dim);
            // 负索引越界守卫：对齐 arch35 逐维检查语义，任一维为负即视为越界；
            // 返回 -1 由 ProcessOneBlock 的范围检查（startInt64_ >= 0）跳过
            if (idxValue < 0) {
                return -1;
            }
            int64_t stride = static_cast<int64_t>(indicesMask_[dim]);
            linearIndex += idxValue * stride;
        }
        return linearIndex;
    }

    __aicore__ inline void ScatterUpdate(uint64_t rowIdx, int64_t linearIndex)
    {
        for (uint64_t tileIdx = 0; tileIdx < scatterTileNum_; ++tileIdx) {
            uint64_t tileLength = (tileIdx == scatterTileNum_ - 1) ? scatterTileTail_ : scatterTileLength_;
            uint64_t gmOffset = rowIdx * scatterLength_ + tileIdx * scatterTileLength_;
            DataCopyExtParams updateCopyParams{1, static_cast<uint32_t>(tileLength * sizeof(T)), 0, 0, 0};
            DataCopyPadExtParams<T> padParams{true, 0, 0, 0};
            DataCopyPad(updateLocal, updatesGm_[gmOffset], updateCopyParams, padParams);
            PipeMte2ToS();

            uint64_t outOffset = ResolveOutOffset<isViewStride0>(static_cast<uint64_t>(linearIndex), scatterLength_,
                                                                 firstDimStrideRows_, varStride0Elements_,
                                                                 tileIdx * scatterTileLength_);
            DataCopyExtParams outParams{1, static_cast<uint32_t>(tileLength * sizeof(T)), 0, 0, 0};
            DataCopyPad(outputGm_[outOffset], updateLocal, outParams);
            PipeMte3ToS();
        }
    }

private:
    GlobalTensor<int64_t> indicesGmInt64_;
    GlobalTensor<T> updatesGm_;
    GlobalTensor<T> outputGm_;

    TBuf<TPosition::VECCALC> indicesBuf;
    TBuf<TPosition::VECCALC> updateBuf;

    LocalTensor<int64_t> indicesInt64Local;
    LocalTensor<T> updateLocal;

        float reduceOut = ReduceSumHalfInterval(xLocal, numCol);
        inQueueX.FreeTensor(xLocal);
        SetFlag<HardEvent::V_S>(eventVS);
        WaitFlag<HardEvent::V_S>(eventVS);
        float rstdValue = 1 / sqrt(reduceOut * avgFactor + epsilon);
        rstdLocal.SetValue(innerProgress, rstdValue);
        SetFlag<HardEvent::S_V>(eventSV);
        WaitFlag<HardEvent::S_V>(eventSV);

        // 3. Y = x * rstd * gamma
        Muls(xLocalFp32, xLocalFp32, rstdValue, numCol);
        PipeBarrier<PIPE_V>();
        Mul(xLocalFp32, xLocalFp32, gammaLocal, numCol);
        PipeBarrier<PIPE_V>();
        LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
        if constexpr (is_same<T, half>::value) {
            Cast(yLocal, xLocalFp32, RoundMode::CAST_NONE, numCol);
        } else {
            Cast(yLocal, xLocalFp32, RoundMode::CAST_RINT, numCol);
        }
        PipeBarrier<PIPE_V>();
        outQueueY.EnQue<T>(yLocal);
    }

    __aicore__ inline void CopyOutY(uint32_t progress)
    {
        LocalTensor<T> yLocal = outQueueY.DeQue<T>();
        DataCopyCustom<T>(yGm[progress], yLocal, numCol);
        outQueueY.FreeTensor(yLocal);
    }

    __aicore__ inline void CopyOutRstd(uint32_t outerProgress, uint32_t num)
    {
        LocalTensor<float> rstdLocal = outQueueRstd.DeQue<float>();
#if __CCE_AICORE__ == 220 || (defined(__NPU_ARCH__) && (__NPU_ARCH__ == 3003 || __NPU_ARCH__ == 3113))
        DataCopyCustom<float>(rstdGm[outerProgress * rowFactor], rstdLocal, num);
#endif
        outQueueRstd.FreeTensor(rstdLocal);
    }

