def _get_layer_metadata(self, metadata) -> DeepseekV41LayerMetadata:
    swa = metadata[self.swa_prefix]
    long_kv = metadata[self.long_kv_source_prefix] if self.long_kv_source_prefix is not None else None
    index_k = metadata[self.index_k_source_prefix] if self.index_k_source_prefix is not None else None
    compressor_state = metadata[self.compressor_state_prefix] if self.compressor_state_prefix is not None else None
    return DeepseekV41LayerMetadata(
        attention=long_kv,
        swa=swa,
        compressor=(
            DeepseekV41CompressorMetadata(long_kv, compressor_state)
            if self.role.is_kv_source and long_kv is not None
            else None
        ),
        indexer=(DeepseekV41IndexerMetadata(index_k) if index_k is not None else None),
    )

@staticmethod
def _apply_rotary(attn, value, cos, sin, *, inverse=False):
    return DeviceOperator.apply_partial_rotary_inplace(
        value, cos, sin, start=attn.nope_head_dim, end=attn.head_dim, inverse=inverse
    )

@staticmethod
def _write_swa_cache(attn, metadata, value):
    cache = attn.dsa_attn.swa_cache_layer.kv_cache[0]
    backend = getattr(attn, "packed_cache_ops", None)
    if backend is not None:
        backend.write_attention_cache(
            cache,
            metadata.flat_slot_mapping[: value.shape[0]],
            value,
            kind="win",
        )
        return
    scatter_cache_sk(cache, metadata.slot_mapping, value)

@staticmethod
def _write_swa_cache_on_main_stream(attn, metadata):
    # Packaged A5 prefill/mixed cache writes must be captured on the
    # current stream even when the independent Q/KV preparation overlaps.
    # A missing prefill classification also cannot qualify as pure decode.
    return getattr(attn, "packed_cache_ops", None) is not None and (
        metadata.num_prefills > 0 or metadata.num_decodes != metadata.num_reqs
    )

@classmethod
def _project_q(cls, attn, hidden_states, cos, sin):
    qr = attn.q_norm(attn.wq_a(hidden_states))
    q = attn.wq_b(qr).unflatten(-1, (-1, attn.head_dim))
    cls._apply_rotary(attn, q, cos, sin)
    return q.to(hidden_states.dtype), qr

@classmethod
def _project_kv(cls, attn, hidden_states, cos, sin):
    kv = attn.kv_norm(attn.wkv(hidden_states)).view(-1, 1, attn.head_dim)
    cls._apply_rotary(attn, kv, cos, sin)
    return kv.squeeze(1)

def rms_norm_cast(x, weight, epsilon):
    """Return fused rounded/FP32 outputs, or None for the normal RMSNorm path."""
    from vllm_ascend.utils import enable_custom_op

    if get_current_hardware_profile().supports(HardwareCapability.RMS_NORM_CAST) and enable_custom_op():
        op = getattr(torch.ops._C_ascend, "npu_rms_norm_cast", None)
        if op is not None:
            return op(x, weight, epsilon)
    return None

@staticmethod
def apply_partial_rotary_inplace(x, cos, sin, *, start, end, inverse=False):
    """Adapt rank and inverse-RoPE arguments without copying the destination."""
    work = x.unsqueeze(-2) if x.ndim == 2 else x
    work = work.unsqueeze(1) if work.ndim == 3 else work
    supports_negate_sin = get_current_hardware_profile().supports(
        HardwareCapability.INPLACE_PARTIAL_ROTARY_MUL_NEGATE_SIN
    )
    torch.ops._C_ascend.inplace_partial_rotary_mul(
        work,
        cos,
        -sin if inverse and not supports_negate_sin else sin,
        rotary_mode="interleave",
        partial_slice=[start, end],
        **({"negate_sin": inverse} if supports_negate_sin else {}),
    )
    return x

@classmethod
def scatter_cache(cls, var: torch.Tensor, indices: torch.Tensor, updates: torch.Tensor) -> None:
    """Dispatch a cache scatter with the original operator's arguments.

    Callers retain their existing views and slices. SK and generic scatter
    receive the original tensors; A5 adapts their layout for PA without
    copying the destination, truncating updates, or filtering slots.
    """
    if cls._is_row_cache(var, indices, updates) and cls._scatter_cache(var, indices, updates):
        return
    torch_npu.npu_scatter_nd_update_(var, indices, updates)

@staticmethod
def _is_row_cache(var, indices, updates) -> bool:
    # This adaptor optimizes row writes: var[N, D], indices[T, 1],
    # updates[T, D]. These checks bound the cache optimization, not SK's
    # full shape support. Other inputs retain the original scatter path.
    if var.ndim != 2 or indices.ndim != 2 or updates.ndim != 2:
        return False
    if indices.shape[1] != 1 or updates.shape != (indices.shape[0], var.shape[1]):
        return False

class _ReplicatedCacheImpl(AscendDSAV41Impl):
    def _global_layer_metadata(self, metadata_by_prefix):
        global_by_prefix = {}
        # The runner also includes DSpark's native DSA metadata in this map.
        # Resolve only the cache planes consumed by this target layer.
        for prefix in (
            self.swa_prefix,
            self.long_kv_source_prefix,
            self.index_k_source_prefix,
            self.compressor_state_prefix,
        ):
            if prefix is None:
                continue
            metadata = metadata_by_prefix[prefix]
            global_by_prefix[prefix] = metadata.global_metadata
        return self._get_layer_metadata(global_by_prefix)


class AscendDSAV41CPImpl(_ReplicatedCacheImpl):
    def _prepare_inputs_and_caches(self, attn, hidden_states, metadata, metadata_by_prefix):
        global_metadata = self._global_layer_metadata(metadata_by_prefix)
        start, _, _, _ = metadata.swa.cp_token_range
        return self._preprocess(attn, hidden_states[start:], hidden_states, metadata, global_metadata)

    def _indexer_hidden_states(self, hidden_states, metadata):
        start, _, _, _ = metadata.swa.cp_token_range
        return hidden_states[start : start + metadata.swa.num_actual_tokens]

    def _select_sparse_indices(self, attn, hidden_states, qr, positions, cos, sin, metadata, prepared_indexer=None):
        if not self.role.has_long_context:
            return None
        if not self.role.is_index_source:
            shared = attn.shared_state
            # ``hidden_states`` still owns the full pre-CP token batch here,
            # while ``qr`` was projected from this rank's local query slice.
            # SparseFlashMla requires cmp_sparse_indices.T to match q.T.
            return shared.topk_indices[: qr.shape[0]]
        return super()._select_sparse_indices(attn, hidden_states, qr, positions, cos, sin, metadata, prepared_indexer)

    def _project_output(self, attn, output, hidden_states, metadata, *, projected):
        _, _, per_rank, _ = metadata.swa.cp_token_range
        padded = output
        if output.shape[0] != per_rank:
            padded = output.new_zeros((per_rank, output.shape[1], output.shape[2]))
            padded[: output.shape[0]] = output
        exchanged = restore_tp_heads(padded, get_tp_group())
        # DSpark's DP/FlashComm padding can extend hidden states beyond the
        # metadata token interval. Restore that suffix before O projection so
        # its TP reduction keeps the caller's padded output layout.
        if exchanged.shape[0] < hidden_states.shape[0]:
            padded_exchange = exchanged.new_zeros((hidden_states.shape[0], *exchanged.shape[1:]))

@contextmanager
def _o_proj_batch(self, projector, *, needs_global_metadata: bool):
    projector._pcp_o_proj_use_full_weight = projector.enable_pcp_o_proj_weight_sharding and needs_global_metadata
    try:
        # V4.1 bypasses DSA forward; prepare persistent aliases during warmup.
        if projector.enable_pcp_o_proj_weight_sharding:
            projector._get_pcp_o_proj_weight_switches()
        yield
    finally:
        for layer, method, state in projector._pcp_o_proj_weight_switches or ():
            if state.handles:
                method.wait_weight_all_gather(state)
            if projector._pcp_o_proj_use_full_weight:
                method.switch_weight(layer, state, use_full_weight=False)
        projector._pcp_o_proj_use_full_weight = False

@staticmethod
def _gather_and_restore_hidden_states(
    hidden_states: torch.Tensor,
    metadata: AscendDSAV41PCPMetadata,
) -> torch.Tensor:
    assert hidden_states.shape[0] == metadata.local_num_tokens_after_padding
    gathered = get_pcp_group().all_gather(hidden_states.contiguous(), dim=0)
    return torch.index_select(gathered, 0, metadata.hidden_restore_idx)

def _prepare_inputs_and_caches(self, attn, hidden_states, metadata, metadata_by_prefix):
    if not isinstance(metadata.swa, AscendDSAV41PCPMetadata):
        return super()._prepare_inputs_and_caches(attn, hidden_states, metadata, metadata_by_prefix)
    # Empty query ranks also join hidden and weight collectives.
    global_hidden_states = self._gather_and_restore_hidden_states(hidden_states, metadata.swa)
    projector = attn.dsa_attn.dsa_attn.impl
    projector._maybe_all_gather_pcp_o_proj_weights()
    global_metadata = self._global_layer_metadata(metadata_by_prefix)
    return self._preprocess(attn, hidden_states, global_hidden_states, metadata, global_metadata)

def forward(self, attn, positions, hidden_states, output=None):
    metadata = get_forward_context().attn_metadata
    needs_global_metadata = metadata is not None and isinstance(metadata[self.swa_prefix], AscendDSAV41PCPMetadata)
    projector = attn.dsa_attn.dsa_attn.impl
    with self._o_proj_batch(projector, needs_global_metadata=needs_global_metadata):
        return super().forward(attn, positions, hidden_states, output)
